def greet(name, language="English"):
    if language == "Tamil":
        print(f"Vanakkam, {name}!")
    elif language == "Hindi":
        print(f"Namaste, {name}!")
    else:
        print(f"Hello, {name}!")

greet("Priya")              # Uses default
greet("Ravi", "Tamil")
greet("Arjun", "Hindi")

def calculate_average(marks):
    total = sum(marks)
    return total / len(marks)

def get_grade(avg):
    if avg >= 90:
        return "S"
    elif avg >= 75:
        return "A"
    elif avg >= 60:
        return "B"
    else:
        return "C"

student_marks = [88, 92, 79, 85, 91]
avg = calculate_average(student_marks)
grade = get_grade(avg)

print(f"Average: {avg}")
print(f"Grade: {grade}")

def min_max(numbers):
    return min(numbers), max(numbers)

scores = [45, 78, 92, 33, 88]
lowest, highest = min_max(scores)
print(f"Lowest: {lowest}, Highest: {highest}")

